pug:
p.iq-promocode--iq-promocode-label.iq-promocode--pt24.iq-promocode--pb5(style="color:{{ label_color }}")
    b {{ label }}
p.iq-promocode--iq-promocode-code(style="background-color:{{ background_color }};border:{{ border }};border-radius:{{ radius }};color:{{ code_color }};padding:{{ padding }}") {{ code }}
p.iq-promocode--iq-promocode-hint.iq-promocode--pt5(style="color:{{ hint_color }}") {{ hint }}

styl:
.iq-promocode--iq-promocode-label{color:{{ label_color }};font-family:Helvetica,Arial,sans-serif!important;font-size:18px;font-weight:400;letter-spacing:0;line-height:26px}
.iq-promocode--iq-promocode-code{background-color:{{ background_color }};border:{{ border }};border-radius:{{ radius }};color:{{ code_color }};font-family:Helvetica,Arial,sans-serif!important;font-size:24px;font-style:normal;font-weight:700;line-height:31px;padding:{{ padding }}}
.iq-promocode--iq-promocode-hint{color:{{ hint_color }};font-family:Helvetica,Arial,sans-serif!important;font-size:16px;font-style:normal;font-weight:400;line-height:24px}

/* втянуто из стилей семьи при скоупе — блок больше не зависит от main.styl */
.iq-promocode--pt24{padding-top:24px}
.iq-promocode--pb5{padding-bottom:5px}
.iq-promocode--pt5{padding-top:5px}
